{"script":"
() => {
  const cards = document.querySelectorAll('[id^="mntl-card-list-card--extendable"]');
  const results = [];
  cards.forEach(card => {
    const title = card.querySelector('span[id^="mntl-card-list-card"]')?.textContent?.trim() 
                  || card.querySelector('h2, h3, .card__title')?.textContent?.trim();
    const ratingEl = card.querySelector('[id^="mntl-recipe-star-rating"]');
    const rating = ratingEl?.getAttribute('data-rating') || ratingEl?.getAttribute('aria-label') || ratingEl?.textContent;
    const ratingsCount = card.querySelector('[id^="mntl-recipe-card-meta"] .mntl-recipe-card-meta__rating-count-number')?.textContent
                        || card.querySelector('[id^="mntl-recipe-card-meta"]')?.textContent;
    const href = card.getAttribute('href') || card.querySelector('a')?.getAttribute('href');
    results.push({title, rating, ratingsCount, href, ariaLabel: card.getAttribute('aria-label')});
  });
  return results;
}"}

